glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
  in vec2 a_uv0;
  out vec2 v_uv0;
#endif
void main() {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
    pos = cc_matViewProj * cc_matWorld * pos;
  #else
    pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
    v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
in vec4 v_color;
#if USE_TEXTURE
  in vec2 v_uv0;
  uniform sampler2D texture;
#endif
uniform HueColor {
  float targetHue;
  float hueRange;
  float hueRotationAngle;
};
vec3 rgbToHsv(vec3 rgb) {
  float r = rgb.r;
  float g = rgb.g;
  float b = rgb.b;
  float minVal = min(min(r, g), b);
  float maxVal = max(max(r, g), b);
  float delta = maxVal - minVal;
  float h = 0.0;
  float s = 0.0;
  float v = maxVal;
  if (delta != 0.0) {
    if (maxVal == r) {
      h = (g - b) / delta;
    } else if (maxVal == g) {
      h = 2.0 + (b - r) / delta;
    } else {
      h = 4.0 + (r - g) / delta;
    }
    h *= 60.0;
    if (h < 0.0) {
      h += 360.0;
    }
    s = delta / maxVal;
  }
  return vec3(h, s, v);
}
vec3 hsvToRgb(vec3 hsv) {
float h = hsv.x;
float s = hsv.y;
float v = hsv.z;
float c = v * s;
float x = c * (1.0 - abs(mod(h / 60.0, 2.0) - 1.0));
float m = v - c;
vec3 rgb;
if (h >= 0.0 && h < 60.0) {
  rgb = vec3(c, x, 0.0);
} else if (h >= 60.0 && h < 120.0) {
  rgb = vec3(x, c, 0.0);
} else if (h >= 120.0 && h < 180.0) {
  rgb = vec3(0.0, c, x);
} else if (h >= 180.0 && h < 240.0) {
  rgb = vec3(0.0, x, c);
} else if (h >= 240.0 && h < 300.0) {
  rgb = vec3(x, 0.0, c);
} else {
  rgb = vec3(c, 0.0, x);
}
return rgb + vec3(m);
}
void main() {
vec4 o = vec4(1, 1, 1, 1);
#if USE_TEXTURE
  o = texture2D(texture, v_uv0);
#endif
vec3 hsv = rgbToHsv(vec3(o.r, o.g, o.b));
float minHue = targetHue - hueRange;
float maxHue = targetHue + hueRange;
if (hsv.x >= minHue && hsv.x <= maxHue) {
  hsv.x += hueRotationAngle;
  if (hsv.x > 360.0) {
    hsv.x -= 360.0;
  }
}
vec3 newColor = hsvToRgb(hsv);
gl_FragColor = vec4(newColor, o.a) * v_color;
}

